// ════════════════════════════════════════════════════════════
// RAVLT — registro por voz. O navegador transcreve a fala; o áudio NÃO é guardado, só o texto.
// As listas de palavras e as normas vêm da configuração importada (cinpsi_ravlt_cfg), nunca do código.
// ════════════════════════════════════════════════════════════
const RV_KEY='cinpsi_ravlt', RV_CFG='cinpsi_ravlt_cfg';
const RV_LOGO='data:image/png;base64,';
const RV_STEPS=['A1','A2','A3','A4','A5','B1','A6','A7','REC','FIM'];
const RV_STOP=new Set(('a o os as e de da do das dos um uma uns umas que eu ele ela nao sim ai ah hum uh eh tipo entao ne ta tem mais ja foi tambem la pra para com mas ou se ate tudo nada outra outro teve era meu minha aqui tava lembro lembrei lembra acho palavra palavras so').split(' '));
let RV=null, RV_STEP=-1, _rvRec=null, _rvOn=false, _rvBase='', _rvTimer=null;
function rvSess(){ const v=finLoad(RV_KEY); return Array.isArray(v)?v:[]; }
function rvCfg(){ const v=finLoad(RV_CFG); return v&&!Array.isArray(v)&&v.listaA&&v.listaA.length===15&&v.listaB&&v.reconhecimento&&v.reconhecimento.length===50?v:null; }
function rvN(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim(); }
function rvDist(a,b){
  const m=a.length,n=b.length; if(!m) return n; if(!n) return m;
  let p=[];for(let j=0;j<=n;j++)p[j]=j;
  for(let i=1;i<=m;i++){ const c=[i]; for(let j=1;j<=n;j++) c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]===b[j-1]?0:1)); p=c; }
  return p[n];
}
function rvSing(t){ return t.replace(/oes$/,'ao').replace(/aes$/,'ao').replace(/s$/,''); }
function rvSimilar(t,w){
  if(t===w) return true;
  if(rvSing(t)===w||t===w+'s') return true;
  return t.length>=5&&w.length>=5&&rvDist(t,w)<=1;
}
// Analisa o texto transcrito contra a lista-alvo. 'outra' é a outra lista (A↔B) para sinalizar a origem de intrusões.
function rvAnalisar(texto,alvo,outra){
  const nA=alvo.map(rvN), nO=(outra||[]).map(rvN);
  const T={texto:texto||'',cont:{},ordem:[],duvidas:[],outras:[],confirmado:false};
  const mapa={};
  rvN(texto).split(' ').filter(Boolean).forEach(t=>{
    if(RV_STOP.has(t)) return;
    let i=nA.indexOf(t); const exato=i>=0;
    if(i<0) i=nA.findIndex(w=>rvSimilar(t,w));
    if(i>=0){ const p=alvo[i]; T.cont[p]=(T.cont[p]||0)+1; if(!T.ordem.includes(p)) T.ordem.push(p); if(!exato) T.duvidas.push({ouvido:t,p,contar:true}); return; }
    if(!mapa[t]){ mapa[t]={p:t,n:0,daOutra:nO.includes(t)||nO.some(w=>rvSimilar(t,w)),tipo:''}; T.outras.push(mapa[t]); }
    mapa[t].n++;
  });
  T.outras.forEach(o=>{ o.tipo=(o.daOutra||o.p.length>=3)?'intrusao':'ignorar'; });
  return T;
}
function rvTot(T){
  if(!T) return {ac:0,rep:0,intr:0};
  const v=Object.values(T.cont||{});
  return {ac:v.filter(c=>c>0).length, rep:v.reduce((s,c)=>s+Math.max(0,c-1),0), intr:(T.outras||[]).filter(o=>o.tipo==='intrusao').reduce((s,o)=>s+o.n,0)};
}
function rvReco(cfg,resp){
  let ac=0,respN=0,hitsA=0,fpB=0,fpO=0;
  cfg.reconhecimento.forEach((it,i)=>{
    const r=(resp||{})[i]; if(!r) return; respN++;
    const certo=it.t==='A'?r==='S':r==='N';
    if(certo) ac++;
    if(it.t==='A'&&r==='S') hitsA++;
    if(it.t!=='A'&&r==='S'){ if(it.t==='B') fpB++; else fpO++; }
  });
  return {ac,respondidas:respN,hitsA,fpB,fpO,indice:ac-35};
}
function rvIdadeTxt(nasc,data){
  if(!nasc||!data) return '';
  const a=new Date(nasc.slice(0,10)+'T12:00:00'), b=new Date(data+'T12:00:00');
  let m=(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth(); if(b.getDate()<a.getDate()) m--;
  return m<0?'':Math.floor(m/12)+' anos e '+(m%12)+' meses';
}
function rvCss(){
  if(document.getElementById('rv-css')) return;
  const s=document.createElement('style'); s.id='rv-css';
  s.textContent='.rv-chip{display:inline-block;padding:3px 9px;border-radius:999px;border:1px solid var(--border);font-size:12px;margin:2px;cursor:pointer;background:#fff}'+
  '.rv-chip.warn{background:#FFF6E0;border-color:#F0C36D;color:#8A5A00}.rv-chip.bad{background:#FBEDEC;border-color:#E3A5A0;color:#B3261E}.rv-chip.off{opacity:.5;text-decoration:line-through}'+
  '.rv-w{display:flex;align-items:center;gap:6px;padding:6px 8px;border:1px solid var(--border);border-radius:8px;font-size:13px;cursor:pointer;background:#fff}.rv-w.on{background:#EAF6EE;border-color:#86C9A0}'+
  '.rv-rec{display:flex;align-items:center;gap:6px;border:1px solid var(--border);border-radius:8px;padding:4px 8px;font-size:13px}.rv-rec span{flex:1}.rv-rec button{border:1px solid var(--border);background:#fff;border-radius:6px;padding:4px 12px;font-weight:700;cursor:pointer}.rv-rec button.on{background:#04253D;color:#fff;border-color:#04253D}'+
  '.rv-step{padding:5px 10px;border-radius:999px;border:1px solid var(--border);background:#fff;font-size:12px;cursor:pointer}.rv-step.cur{background:#04253D;color:#fff;border-color:#04253D}.rv-step.done{background:#EAF6EE;border-color:#86C9A0;color:#14653A}'+
  '.rv-rec-on{animation:rvp 1s infinite}@keyframes rvp{50%{opacity:.4}}';
  document.head.appendChild(s);
}
function rvHtmlAba(p,id,nome){
  const cfg=rvCfg();
  const ls=rvSess().filter(x=>String(x.pacNome||'').toLowerCase()===String(nome||'').toLowerCase()).sort((a,b)=>String(b.criado||'').localeCompare(String(a.criado||'')));
  const topo=cfg?`<button class="btn-primary" onclick="rvNova()">🎙️ Nova aplicação do RAVLT</button>`:
    `<div style="background:#FFF6E0;border:1px solid #F0C36D;border-radius:10px;padding:12px;font-size:13px;line-height:1.5">As listas de palavras do RAVLT ainda não foram cadastradas neste sistema. Importe o arquivo de configuração (listas e normas) uma única vez.<br><button class="btn-primary" style="margin-top:8px" onclick="rvImportarCfg()">📥 Importar configuração do RAVLT</button></div>`;
  const lista=ls.length?ls.map(s=>{
    const resumo=['A1','A2','A3','A4','A5','B1','A6','A7'].map(k=>k+': '+((s.tent||{})[k]&&s.tent[k].confirmado?rvTot(s.tent[k]).ac:'—')).join(' · ');
    const ok=s.status==='registrado';
    return `<div style="border:1px solid var(--border);border-radius:8px;padding:10px 12px;margin-top:8px;background:${ok?'#f0fdf4':'var(--surface)'}">
      <div style="font-size:13px"><b>RAVLT</b> · ${esc(preCadFmtData(s.data))} · ${ok?'✅ registrado':'⏳ em andamento'}</div>
      <div style="font-size:12px;color:var(--text3);margin-top:4px">${esc(resumo)}</div>
      <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap">
        <button class="btn-primary" style="padding:4px 10px;font-size:12px" onclick="rvAbrir('${s.id}')">${ok?'Abrir':'Continuar'}</button>
        <button class="btn-ghost" style="padding:4px 10px;font-size:12px" onclick="rvPdf('${s.id}')">📄 PDF do registro</button>
        ${CU.role==='admin'?`<button class="btn-ghost" style="padding:4px 10px;font-size:12px;color:#b91c1c" onclick="rvExcluir('${s.id}')">🗑️ Excluir</button>`:''}
      </div></div>`;}).join(''):'<p style="font-size:13px;color:var(--text3);margin-top:12px">Nenhuma aplicação do RAVLT registrada para este paciente.</p>';
  const cfgBtn=cfg&&CU.role==='admin'?`<div style="margin-top:14px"><button class="btn-ghost" style="font-size:12px" onclick="rvImportarCfg()">⚙️ Atualizar configuração (listas e normas)</button></div>`:'';
  return topo+lista+cfgBtn;
}
function rvImportarCfg(){
  const inp=document.createElement('input'); inp.type='file'; inp.accept='.json';
  inp.onchange=e=>{ const f=e.target.files[0]; if(!f) return; const r=new FileReader();
    r.onload=ev=>{ try{
      const j=JSON.parse(ev.target.result);
      if(j.tipo!=='ravlt_config'||!Array.isArray(j.listaA)||j.listaA.length!==15||!Array.isArray(j.listaB)||j.listaB.length!==15||!Array.isArray(j.reconhecimento)||j.reconhecimento.length!==50) throw new Error('arquivo de configuração inválido');
      finSave(RV_CFG,j); toast('✅ Configuração do RAVLT importada.'); if(document.getElementById('modal-testes')) teRenderFicha();
    }catch(err){ toast('❌ '+err.message); } };
    r.readAsText(f); };
  inp.click();
}
function rvSalvar(){
  const l=rvSess().filter(x=>x.id!==RV.id); l.push(JSON.parse(JSON.stringify(RV))); finSave(RV_KEY,l);
}
function rvNova(){
  const nome=teNomeAtual, p=tePacientes().find(x=>tePacNome(x).toLowerCase()===nome.toLowerCase())||{};
  const hoje=new Date().toISOString().slice(0,10);
  RV={id:'rv_'+Date.now(),pacNome:nome,pacId:String(p.id||''),nasc:teNascISO(p.nascimento||p.nasc),sexo:'',escolaridade:'',examinador:(CU&&CU.nome)||'',data:hoje,consentimentoAudio:false,status:'em_andamento',tent:{},reco:{resp:{}},obs:'',criado:new Date().toISOString(),criadoPor:(CU&&CU.nome)||''};
  RV_STEP=-1; rvRender();
}
function rvAbrir(id){
  const s=rvSess().find(x=>x.id===id); if(!s) return;
  RV=JSON.parse(JSON.stringify(s));
  if(s.status==='registrado') RV_STEP=9;
  else { const i=RV_STEPS.findIndex(k=>k==='REC'?!RV.recOk:k==='FIM'?true:!(RV.tent[k]&&RV.tent[k].confirmado)); RV_STEP=i<0?9:i; }
  rvRender();
}
function rvFechar(){
  _rvOn=false; try{ if(_rvRec) _rvRec.stop(); }catch(e){}
  if(_rvTimer){ clearInterval(_rvTimer); _rvTimer=null; }
  if(RV&&RV_STEP>=0) rvSalvar();
  document.getElementById('modal-ravlt')?.remove();
  RV=null; if(document.getElementById('modal-testes')) teRenderFicha();
}
function rvIr(i){ if(_rvOn) rvParar(true); RV_STEP=i; rvRender(); }
function rvRender(){
  rvCss();
  let mo=document.getElementById('modal-ravlt');
  if(!mo){ mo=document.createElement('div'); mo.className='modal-overlay open'; mo.id='modal-ravlt'; document.body.appendChild(mo); }
  const cfg=rvCfg();
  const chips=RV_STEPS.map((k,i)=>{ const done=k==='REC'?RV.recOk:k==='FIM'?RV.status==='registrado':(RV.tent[k]&&RV.tent[k].confirmado); const lbl=k==='REC'?'Reconhec.':k==='FIM'?'Final':k;
    return `<button class="rv-step ${i===RV_STEP?'cur':done?'done':''}" ${RV_STEP<0?'disabled':''} onclick="rvIr(${i})">${lbl}${done&&i!==RV_STEP?' ✓':''}</button>`; }).join(' ');
  let corpo='';
  if(RV_STEP<0) corpo=rvHtmlCab();
  else { const k=RV_STEPS[RV_STEP]; corpo=k==='REC'?rvHtmlReco(cfg):k==='FIM'?rvHtmlFim(cfg):rvHtmlTent(k,cfg); }
  mo.innerHTML=`<div class="modal" style="max-width:780px;max-height:94vh;overflow:auto">
    <div class="modal-header"><div class="modal-title">🧠 RAVLT — ${esc(RV.pacNome)}</div><button class="modal-close" onclick="rvFechar()">×</button></div>
    <div style="padding:10px 20px 0;display:flex;gap:6px;flex-wrap:wrap">${chips}</div>
    <div style="padding:14px 20px 20px">${corpo}</div></div>`;
  if(_rvTimer){ clearInterval(_rvTimer); _rvTimer=null; }
  _rvTimer=setInterval(rvTick,1000); rvTick();
}
function rvTick(){
  const el=document.getElementById('rv-timer'); if(!el||!RV) return;
  if(!RV.tA6){ el.textContent='O intervalo de 20 minutos começa quando a A6 for confirmada.'; el.style.color='var(--text3)'; return; }
  const resta=1200000-(Date.now()-RV.tA6);
  if(resta<=0){ el.textContent='✅ Intervalo de 20 minutos concluído. A7 liberada.'; el.style.color='#15803d'; }
  else { const m=Math.floor(resta/60000), s=Math.floor(resta%60000/1000); el.textContent='⏳ Faltam '+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+' para a A7 (20 min após a A6).'; el.style.color='#b45309'; }
}
function rvHtmlCab(){
  return `<div class="form-grid">
    <div class="form-group"><label class="form-label">Data da aplicação</label><input class="form-input" type="date" id="rv-data" value="${esc(RV.data)}"></div>
    <div class="form-group"><label class="form-label">Idade</label><input class="form-input" disabled value="${esc(rvIdadeTxt(RV.nasc,RV.data)||'—')}"></div>
    <div class="form-group"><label class="form-label">Sexo</label><select class="form-select" id="rv-sexo"><option value="">Selecione...</option><option${RV.sexo==='F'?' selected':''} value="F">Feminino</option><option${RV.sexo==='M'?' selected':''} value="M">Masculino</option></select></div>
    <div class="form-group"><label class="form-label">Escolaridade / série</label><input class="form-input" id="rv-esc" value="${esc(RV.escolaridade)}"></div>
    <div class="form-group full"><label class="form-label">Examinador</label><input class="form-input" id="rv-exam" value="${esc(RV.examinador)}"></div>
  </div>
  <label style="display:flex;gap:8px;align-items:flex-start;font-size:13px;margin-top:12px;line-height:1.5"><input type="checkbox" id="rv-cons" ${RV.consentimentoAudio?'checked':''} style="margin-top:3px"><span>O responsável autorizou o uso de áudio para transcrição (consta no Termo de Adesão). <b>O áudio não é guardado pelo sistema: só o texto transcrito.</b> A transcrição é feita pelo navegador.</span></label>
  <div style="margin-top:16px;text-align:right"><button class="btn-primary" onclick="rvIniciar()">Iniciar aplicação →</button></div>`;
}
function rvIniciar(){
  if(!document.getElementById('rv-cons').checked){ toast('Confirme a autorização de áudio para iniciar.'); return; }
  RV.data=document.getElementById('rv-data').value||RV.data; RV.sexo=document.getElementById('rv-sexo').value; RV.escolaridade=document.getElementById('rv-esc').value.trim(); RV.examinador=document.getElementById('rv-exam').value.trim(); RV.consentimentoAudio=true;
  rvSalvar(); RV_STEP=0; rvRender();
}
function rvListas(k,cfg){ return k==='B1'?{alvo:cfg.listaB,outra:cfg.listaA}:{alvo:cfg.listaA,outra:cfg.listaB}; }
function rvHtmlTent(k,cfg){
  const L=rvListas(k,cfg); const T=RV.tent[k]||(RV.tent[k]=rvAnalisar('',L.alvo,L.outra));
  const dica={A1:'Leia a lista A e, ao terminar, toque em Gravar para registrar a evocação da criança.',B1:'Lista B (distrator): leia e grave a evocação.',A6:'Logo após a B1, sem reler a lista A. Ao confirmar, o intervalo de 20 minutos começa.',A7:'Evocação tardia, sem reler a lista.'}[k]||'Aplique conforme o manual e grave a evocação da criança.';
  return `<div style="font-size:13px;color:var(--text2);margin-bottom:10px">${esc(dica)}</div>
  ${k==='A7'?'<div id="rv-timer" style="font-size:13px;font-weight:600;margin-bottom:10px"></div>':''}
  <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
    <button class="btn-primary" id="rv-btn-rec" onclick="rvGravar('${k}')">🎙️ Gravar ${k}</button>
    <button class="btn-ghost" id="rv-btn-stop" style="display:none" onclick="rvParar()">⏹ Parar</button>
    <span id="rv-ind" style="font-size:12px;color:#B3261E"></span>
  </div>
  <label class="form-label" style="margin-top:12px">Transcrição (pode corrigir e tocar em Reprocessar)</label>
  <textarea class="form-input" id="rv-texto" rows="3" style="width:100%">${esc(T.texto)}</textarea>
  <button class="btn-ghost" style="font-size:12px;margin-top:6px" onclick="rvReprocessar('${k}')">↻ Reprocessar texto</button>
  <div id="rv-conf" style="margin-top:14px">${rvHtmlConf(k,cfg)}</div>
  <div style="display:flex;justify-content:space-between;margin-top:16px">
    <button class="btn-ghost" ${RV_STEP===0?'disabled':''} onclick="rvIr(${RV_STEP-1})">← Anterior</button>
    <button class="btn-primary" onclick="rvConfirmar('${k}')">Confirmar ${k} e continuar →</button>
  </div>`;
}
function rvHtmlConf(k,cfg){
  const L=rvListas(k,cfg), T=RV.tent[k], tot=rvTot(T);
  const grade=L.alvo.map((w,i)=>{ const c=T.cont[w]||0; return `<label class="rv-w ${c>0?'on':''}"><input type="checkbox" ${c>0?'checked':''} onchange="rvPal('${k}',${i},this.checked)"> ${esc(w)}${c>1?` <b style="color:#8A5A00">×${c}</b>`:''}</label>`; }).join('');
  const duv=T.duvidas.length?`<div style="margin-top:10px;font-size:12px;color:#8A5A00"><b>Confira (o reconhecimento ouviu algo parecido):</b><br>${T.duvidas.map((d,j)=>`<span class="rv-chip warn ${d.contar?'':'off'}" onclick="rvDuv('${k}',${j})">ouvido “${esc(d.ouvido)}” → ${esc(d.p)} ${d.contar?'✓ conta':'✗ não conta'}</span>`).join('')}</div>`:'';
  const out=T.outras.length?`<div style="margin-top:10px;font-size:12px"><b>Outras palavras ouvidas</b> (toque para alternar entre intrusão e ignorar):<br>${T.outras.map((o,j)=>`<span class="rv-chip ${o.tipo==='intrusao'?'bad':'off'}" onclick="rvOutra('${k}',${j})">${esc(o.p)}${o.n>1?' ×'+o.n:''}${o.daOutra?' (outra lista)':''} — ${o.tipo==='intrusao'?'intrusão':'ignorar'}</span>`).join('')}</div>`:'';
  return `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:6px">${grade}</div>${duv}${out}
  <div style="margin-top:12px;font-size:14px"><b>Acertos: ${tot.ac}</b> de 15 · Repetições: ${tot.rep} · Intrusões: ${tot.intr}</div>`;
}
function rvAtualConf(k){ const el=document.getElementById('rv-conf'); if(el) el.innerHTML=rvHtmlConf(k,rvCfg()); }
function rvPal(k,i,on){
  const T=RV.tent[k], w=rvListas(k,rvCfg()).alvo[i];
  if(on){ T.cont[w]=Math.max(1,T.cont[w]||0); if(!T.ordem.includes(w)) T.ordem.push(w); } else { T.cont[w]=0; T.ordem=T.ordem.filter(x=>x!==w); }
  rvAtualConf(k);
}
function rvDuv(k,j){
  const T=RV.tent[k], d=T.duvidas[j]; d.contar=!d.contar;
  if(d.contar){ T.cont[d.p]=(T.cont[d.p]||0)+1; if(!T.ordem.includes(d.p)) T.ordem.push(d.p); }
  else { T.cont[d.p]=Math.max(0,(T.cont[d.p]||0)-1); if(!T.cont[d.p]) T.ordem=T.ordem.filter(x=>x!==d.p); }
  rvAtualConf(k);
}
function rvOutra(k,j){ const o=RV.tent[k].outras[j]; o.tipo=o.tipo==='intrusao'?'ignorar':'intrusao'; rvAtualConf(k); }
function rvReprocessar(k){
  const L=rvListas(k,rvCfg()); const txt=document.getElementById('rv-texto').value;
  const antes=RV.tent[k]; RV.tent[k]=rvAnalisar(txt,L.alvo,L.outra); RV.tent[k].confirmado=!!(antes&&antes.confirmado);
  rvAtualConf(k);
}
function rvConfirmar(k){
  const txt=document.getElementById('rv-texto');
  if(txt&&txt.value!==RV.tent[k].texto){
    if(confirm('A transcrição foi alterada e ainda não foi reprocessada. Reprocessar agora? (OK = reprocessa e você confere de novo; Cancelar = mantém a conferência atual)')){ rvReprocessar(k); return; }
    RV.tent[k].texto=txt.value;
  }
  if(_rvOn) rvParar(false);
  RV.tent[k].confirmado=true;
  if(k==='A6') RV.tA6=Date.now();
  rvSalvar(); RV_STEP++; rvRender();
}
// ── gravação (Web Speech API do navegador) ──
function rvGravar(k){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){ toast('Este navegador não faz reconhecimento de voz. Use o Chrome, ou digite o texto na caixa.'); return; }
  const ta=document.getElementById('rv-texto'); _rvBase=(ta.value||'').trim(); _rvOn=true; window._rvK=k;
  rvUiGrav(true); rvIniciarRec(SR);
}
function rvIniciarRec(SR){
  const r=new SR(); r.lang='pt-BR'; r.continuous=true; r.interimResults=true; r.maxAlternatives=1;
  r.onresult=e=>{ let f='',t=''; for(let i=0;i<e.results.length;i++){ const x=e.results[i]; if(x.isFinal) f+=x[0].transcript+' '; else t+=x[0].transcript+' '; }
    const ta=document.getElementById('rv-texto'); if(ta) ta.value=(_rvBase+' '+f+t).trim(); };
  r.onerror=e=>{ if(e.error==='not-allowed'||e.error==='service-not-allowed'){ _rvOn=false; toast('Permita o uso do microfone no navegador (cadeado ao lado do endereço).'); } else if(e.error==='audio-capture'){ _rvOn=false; toast('Microfone não encontrado.'); } };
  r.onend=()=>{
    if(_rvOn){ const ta=document.getElementById('rv-texto'); _rvBase=ta?(ta.value||'').trim():_rvBase; try{ rvIniciarRec(SR); }catch(e){ _rvOn=false; rvUiGrav(false); } }
    else { rvUiGrav(false); if(window._rvK&&document.getElementById('rv-texto')&&RV&&RV.tent[window._rvK]) rvReprocessar(window._rvK); }
  };
  _rvRec=r; try{ r.start(); }catch(e){ _rvOn=false; rvUiGrav(false); }
}
function rvParar(reproc){
  _rvOn=false; try{ if(_rvRec) _rvRec.stop(); }catch(e){}
  rvUiGrav(false); if(reproc&&window._rvK&&document.getElementById('rv-texto')&&RV&&RV.tent[window._rvK]) rvReprocessar(window._rvK);
}
function rvUiGrav(on){
  const a=document.getElementById('rv-btn-rec'), b=document.getElementById('rv-btn-stop'), i=document.getElementById('rv-ind');
  if(a) a.style.display=on?'none':''; if(b) b.style.display=on?'':'none';
  if(i){ i.textContent=on?'● gravando — a criança pode falar':''; i.className=on?'rv-rec-on':''; }
}
// ── reconhecimento ──
function rvHtmlReco(cfg){
  const r=rvReco(cfg,RV.reco.resp);
  const grade=cfg.reconhecimento.map((it,i)=>{ const v=RV.reco.resp[i]; return `<div class="rv-rec"><span>${esc(it.p)}</span><button class="${v==='S'?'on':''}" onclick="rvResp(${i},'S')">S</button><button class="${v==='N'?'on':''}" onclick="rvResp(${i},'N')">N</button></div>`; }).join('');
  return `<div style="font-size:13px;color:var(--text2);margin-bottom:10px">Leia as 50 palavras. Para cada uma, toque em <b>S</b> (a criança diz que estava na lista) ou <b>N</b> (diz que não estava).</div>
  <div id="rv-reco-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:6px">${grade}</div>
  <div style="margin-top:12px;font-size:14px"><b>Respondidas: ${r.respondidas}/50</b> · Acertos: ${r.ac}</div>
  <div style="display:flex;justify-content:space-between;margin-top:16px"><button class="btn-ghost" onclick="rvIr(${RV_STEP-1})">← Anterior</button><button class="btn-primary" onclick="rvRecOk()">Confirmar reconhecimento e continuar →</button></div>`;
}
function rvResp(i,v){
  if(RV.reco.resp[i]===v) delete RV.reco.resp[i]; else RV.reco.resp[i]=v;
  const sc=document.getElementById('modal-ravlt').querySelector('.modal').scrollTop;
  rvRender(); document.getElementById('modal-ravlt').querySelector('.modal').scrollTop=sc;
}
function rvRecOk(){
  const r=rvReco(rvCfg(),RV.reco.resp);
  if(r.respondidas<50&&!confirm('Só '+r.respondidas+' de 50 palavras foram respondidas. Continuar mesmo assim?')) return;
  RV.recOk=true; rvSalvar(); RV_STEP++; rvRender();
}
// ── final ──
function rvHtmlFim(cfg){
  const cab=['A1','A2','A3','A4','A5','B1','A6','A7'];
  const lin=(t,f)=>`<tr><td style="padding:4px 8px;font-weight:600">${t}</td>${cab.map(k=>`<td style="text-align:center">${f(rvTot((RV.tent||{})[k]))}</td>`).join('')}</tr>`;
  const r=rvReco(cfg,RV.reco.resp);
  return `<div style="overflow:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#F6F8FB"><th></th>${cab.map(k=>`<th style="padding:4px 8px">${k}</th>`).join('')}</tr></thead><tbody>${lin('Acertos',t=>t.ac)}${lin('Repetições',t=>t.rep)}${lin('Intrusões',t=>t.intr)}</tbody></table></div>
  <div style="margin-top:10px;font-size:13px">Reconhecimento: <b>${r.ac}</b> acertos de 50 · falsos positivos: ${r.fpB+r.fpO} (lista B: ${r.fpB}) · índice (acertos − 35): <b>${r.indice}</b></div>
  <label class="form-label" style="margin-top:12px">Observações</label>
  <textarea class="form-input" id="rv-obs" rows="3" style="width:100%">${esc(RV.obs||'')}</textarea>
  <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px">
    <button class="btn-primary" onclick="rvFinalizar(false)">💾 Salvar registro</button>
    <button class="btn-ghost" onclick="rvFinalizar(true)">📄 Salvar e gerar PDF do registro</button>
  </div>
  <p style="font-size:12px;color:var(--text3);margin-top:10px">O registro guarda as respostas. A pontuação normativa (percentil e classificação) é a etapa de correção, feita depois.</p>`;
}
function rvFinalizar(pdf){
  RV.obs=(document.getElementById('rv-obs')||{value:RV.obs}).value; RV.status='registrado'; RV.registradoEm=new Date().toISOString();
  rvSalvar(); toast('✅ Registro do RAVLT salvo.');
  if(pdf) rvPdf(RV.id); else rvRender();
}
function rvExcluir(id){
  if(CU.role!=='admin'||!confirm('Excluir esta aplicação do RAVLT? Não pode ser desfeito.')) return;
  finSave(RV_KEY,rvSess().filter(x=>x.id!==id)); if(document.getElementById('modal-testes')) teRenderFicha();
}
// ── PDF de registro (layout CINPSI; impresso pelo navegador → "Salvar como PDF") ──
function rvPdf(id){
  const s=(RV&&RV.id===id?RV:null)||rvSess().find(x=>x.id===id), cfg=rvCfg(); if(!s||!cfg){ toast('Registro ou configuração não encontrados.'); return; }
  const cab=['A1','A2','A3','A4','A5','B1','A6','A7'];
  const nLin=Math.max(1,...cab.map(k=>(((s.tent||{})[k]||{}).ordem||[]).length));
  const cel=(k,i)=>{ const T=(s.tent||{})[k]; const w=T&&T.ordem?T.ordem[i]:''; const c=w&&T.cont?T.cont[w]:0; return w?esc(w)+(c>1?' <small>(×'+c+')</small>':''):''; };
  let linhas=''; for(let i=0;i<nLin;i++) linhas+=`<tr><td class="n">${i+1}</td>${cab.map(k=>`<td>${cel(k,i)}</td>`).join('')}</tr>`;
