  const intr=cab.map(k=>{ const T=(s.tent||{})[k]; return T?T.outras.filter(o=>o.tipo==='intrusao').map(o=>esc(o.p)+(o.n>1?' ×'+o.n:'')).join(', '):''; });
  const r=rvReco(cfg,s.reco&&s.reco.resp);
