  .hd{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #04253D;padding-bottom:8px;margin-bottom:10px}.hd img{height:54px}.hd .t{text-align:right}.hd h1{font-size:16px;margin:0;color:#04253D}.hd p{margin:2px 0 0;color:#586374}
  .id{display:grid;grid-template-columns:repeat(3,1fr);gap:4px 14px;border:1px solid #cdd5df;border-radius:6px;padding:8px;margin-bottom:10px}.id div b{color:#04253D}
  h2{font-size:12px;color:#fff;background:#04253D;padding:4px 8px;border-radius:4px;margin:12px 0 6px}
  table{width:100%;border-collapse:collapse}th,td{border:1px solid #b9c3cf;padding:3px 5px;text-align:center}th{background:#e9eff6}td.n{background:#f3f6fa;width:22px;color:#586374}
  tfoot td{font-weight:700;background:#f3f6fa}.sm td{font-size:10px}
  .rg{display:grid;grid-template-columns:repeat(5,1fr);gap:3px}.rc{display:flex;gap:4px;border:1px solid #cdd5df;border-radius:4px;padding:2px 5px}.rc span{flex:1;text-align:left}.rc.x{background:#FBEDEC;border-color:#E3A5A0}.rc i{width:12px;font-style:normal}
  .ob{border:1px solid #cdd5df;border-radius:6px;padding:8px;min-height:50px;white-space:pre-wrap}.ft{margin-top:14px;font-size:9px;color:#6b7686;border-top:1px solid #cdd5df;padding-top:6px}
  </style></head><body>
  <div class="hd"><img src="${RV_LOGO}"><div class="t"><h1>Registro de aplicação — RAVLT</h1><p>Teste de Aprendizagem Auditivo-Verbal de Rey · coleta de respostas</p></div></div>
  <div class="id"><div><b>Paciente:</b> ${esc(s.pacNome)}</div><div><b>Nascimento:</b> ${s.nasc?esc(preCadFmtData(s.nasc.slice(0,10))):'—'}</div><div><b>Idade na aplicação:</b> ${esc(rvIdadeTxt(s.nasc,s.data)||'—')}</div>
  <div><b>Data:</b> ${esc(preCadFmtData(s.data))}</div><div><b>Sexo:</b> ${s.sexo==='F'?'Feminino':s.sexo==='M'?'Masculino':'—'}</div><div><b>Escolaridade:</b> ${esc(s.escolaridade||'—')}</div><div style="grid-column:1/-1"><b>Examinador:</b> ${esc(s.examinador||'—')}</div></div>
  <h2>Palavras evocadas por tentativa (na ordem em que a criança falou)</h2>
  <table><thead><tr><th>#</th>${cab.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${linhas}</tbody>
  <tfoot><tr><td>Total</td>${tot.map(t=>`<td>${t.ac}</td>`).join('')}</tr></tfoot></table>
  <h2>Intrusões e repetições</h2>
  <table class="sm"><thead><tr><th></th>${cab.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>
  <tr><td><b>Intrusões</b></td>${intr.map((x,i)=>`<td>${x||'—'}${tot[i].intr?'<br><b>('+tot[i].intr+')</b>':''}</td>`).join('')}</tr>
  <tr><td><b>Repetições</b></td>${tot.map(t=>`<td>${t.rep}</td>`).join('')}</tr></tbody></table>
